/**
 * The parts of docs/api/cli-reference.json and docs/api/mcp-tools.json the
 * CLI and MCP references read (generated by `bun run openapi` in web/,
 * docs/plan/21-reference-and-examples.md).
 */
import type { JsonSchema } from "@/lib/openapi/openapi-types";

export type ReferencedOperation = {
  method: string;
  path: string;
  operation_id: string;
  summary: string;
  area_slug: string;
  selector: { input: string; value?: string; isGiven?: boolean } | null;
};

export type InputTarget = { name: string; location: string } | null;

export type CliArgument = {
  name: string;
  input: InputTarget;
  type: string;
  allowed_values: unknown[] | null;
  description: string;
  example: unknown;
  reads_file: boolean;
};

export type CliFlag = {
  flag: string;
  input: InputTarget;
  type: string;
  value_label: string | null;
  is_required: boolean;
  is_repeatable: boolean;
  takes_json: boolean;
  allowed_values: unknown[] | null;
  description: string;
  example: unknown;
};

export type CliCommand = {
  command: string;
  slug: string;
  usage: string;
  summary: string;
  area: string;
  area_slug: string;
  operations: ReferencedOperation[];
  aliases: string[];
  arguments: CliArgument[];
  flags: CliFlag[];
  example: string;
  output: string | null;
  exit_codes: number[];
  mcp: string[];
  ui: string[];
};

export type CliReference = {
  global_flags: {
    flag: string;
    value_label: string | null;
    description: string;
  }[];
  exit_codes: { code: number; meaning: string }[];
  commands: CliCommand[];
};

export type McpProperty = {
  name: string;
  input: InputTarget;
  type: string;
  is_required: boolean;
  allowed_values: unknown[] | null;
  description: string;
  example: unknown;
};

export type McpTool = {
  name: string;
  toolset: string;
  summary: string;
  area: string;
  area_slug: string;
  operations: ReferencedOperation[];
  aliases: string[];
  annotations: {
    read_only_hint: boolean;
    destructive_hint: boolean;
    idempotent_hint: boolean;
  };
  properties: McpProperty[];
  input_schema: JsonSchema;
  example_arguments: Record<string, unknown>;
  output: string | null;
  cli: string[];
  ui: string[];
};

export type McpResource = {
  uri: string;
  slug: string;
  summary: string;
  mime_type: string;
  area: string;
  area_slug: string;
  parameters: McpProperty[];
  operation: ReferencedOperation;
  cli: string;
  ui: string;
};

export type McpExemption = {
  operation: ReferencedOperation;
  reason: string;
  cli: string;
};

export type McpReference = {
  tools: McpTool[];
  resources: McpResource[];
  exemptions: McpExemption[];
};
